import{_ as a,o as e,c as n,a0 as t}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"模組指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/module.md","filePath":"zh_TW/guide/module.md"}'),l={name:"zh_TW/guide/module.md"};function p(i,s,o,c,d,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="module-guide" tabindex="-1">模組指南 <a class="header-anchor" href="#module-guide" aria-label="Permalink to &quot;模組指南 {#module-guide}&quot;">​</a></h1><p>KernelSU 提供了一個模組機制，它可以在保持系統分割區完整性的同時達到修改系統分割區的效果；這種機制一般被稱為 systemless (無系統修改)。</p><p>KernelSU 的模組運作機制與 Magisk 幾乎相同，如果您熟悉 Magisk 模組的開發，那麼開發 KernelSU 的模組大同小異，您可以跳過下列有關模組的介紹，只需要瞭解 <a href="./difference-with-magisk.html">KernelSU 模組與 Magisk 模組的差異</a>。</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE 僅在修改系統檔案時需要</p><p>KernelSU 使用 <a href="./metamodule.html">metamodule</a> 架構來掛載 <code>system</code> 目錄。<strong>僅當您的模組需要修改 <code>/system</code> 檔案時</strong>(透過 <code>system</code> 目錄)，您才需要安裝 metamodule(如 <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>)。其他模組功能如腳本、sepolicy 規則和 system.prop 無需 metamodule 即可運作。</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>KernelSU 的模組支援顯示互動介面，請參閱 <a href="./module-webui.html">WebUI 文檔</a>.</p><h2 id="模組配置" tabindex="-1">模組配置 <a class="header-anchor" href="#模組配置" aria-label="Permalink to &quot;模組配置&quot;">​</a></h2><p>KernelSU 提供了一個內建的配置系統，允許模組儲存持久化或暫時的鍵值設定。詳情請參閱<a href="./module-config.html">模組配置文檔</a>。</p><h2 id="一次性腳本" tabindex="-1">一次性腳本 <a class="header-anchor" href="#一次性腳本" aria-label="Permalink to &quot;一次性腳本&quot;">​</a></h2><p>模組 ZIP 也可以是一次性腳本：KernelSU 管理器只執行它一次，而不是安裝它。詳情請參閱<a href="./module-script.html">一次性腳本文檔</a>。</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>KernelSU 提供了一個完備的 BusyBox 二進位檔案 (包括完整的 SELinux 支援)。可執行檔位於 <code>/data/adb/ksu/bin/busybox</code>。 KernelSU 的 BusyBox 支援執行時可切換的 &quot;ASH 獨立模式&quot;。 ASH 獨立模式在執行 BusyBox 時，每個命令都會直接使用 BusyBox 中內建的應用程式，而不論 <code>PATH</code> 的設定為何。 例如，<code>ls</code>、<code>rm</code>、<code>chmod</code> 等命令將不會使用 <code>PATH</code> 中設定的命令 (在 Android 的狀況下，預設狀況下分別為 <code>/system/bin/ls</code>、<code>/system/bin/rm</code> 和 <code>/system/bin/chmod</code>)，而是直接呼叫 BusyBox 內建的應用程式。 這確保了腳本始終在可預測的環境中執行，並始終具有完整的命令套件，不論它執行在哪個 Android 版本上。 要強制下一個命令不使用 BusyBox，您必須使用完整路徑呼叫可執行檔。</p><p>每個基於 KernelSU 上下文的腳本都將在 BusyBox 的獨立模式執行。對於第三方開發人員而言，這包括所有開機腳本和模組安裝腳本。</p><p>對於想要在 KernelSU 之外使用這個「獨立模式」功能的使用者，有兩種啟用方法：</p><ol><li>將環境變數 <code>ASH_STANDALONE</code> 設為 <code>1</code>。例如：<code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>使用命令列選項切換：<code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>為了確保所有後續的 <code>sh</code> shell 都在獨立模式下執行，第一種是首選方法 (這也是 KernelSU 和 KernelSU 管理器內部使用的方法)，因為環境變數會被繼承到子執行緒中。</p><div class="tip custom-block"><p class="custom-block-title">與 Magisk 的差異</p><p>KernelSU 的 BusyBox 現在是直接使用 Magisk 專案編譯的二進位檔案，<strong>感謝 Magisk！</strong> 因此，您完全不必擔心 BusyBox 腳本與在 Magisk 和 KernelSU 之間的相容性問題，因為它們完全相同！</p></div><h2 id="kernelsu-modules" tabindex="-1">KernelSU 模組 <a class="header-anchor" href="#kernelsu-modules" aria-label="Permalink to &quot;KernelSU 模組 {#kernelsu-modules}&quot;">​</a></h2><p>KernelSU 模組是一個放置於 <code>/data/adb/modules</code> 且滿足下列結構的資料夾：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- 模組的資料夾名稱與模組 ID 相同</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 模組識別 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- 這個檔案儲存與模組相關的中繼資料，例如模組 ID、版本等</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 主要內容 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- 這個資料夾會在 skip_mount 不存在時被掛接至系統</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 狀態旗標 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- 如果這個檔案存在，那麼 KernelSU 將不會掛接您的系統資料夾</span></span>
<span class="line"><span>│   ├── disable             &lt;--- 如果這個檔案存在，那麼模組將會被停用</span></span>
<span class="line"><span>│   ├── remove              &lt;--- 如果這個檔案存在，那麼模組將會在下次重新開機時被移除</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 選用檔案 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- 這個腳本將會在 post-fs-data 中執行</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- 這個腳本將會在 late_start 服務中執行</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- 這個腳本將會在 KernelSU 移除模組時執行</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- 這個檔案中指定的屬性將會在系統啟動時透過 resetprop 變更</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- 這個檔案中的 SELinux 原則將會在系統開機時載入</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- 此目錄下的 .rc 檔案將在啟動時注入 init.rc</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 自動產生的目錄，不要手動建立或修改！ ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- A symlink to $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- A symlink to $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- A symlink to $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 允許的其他額外檔案/資料夾 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">與 Magisk 的差異</p><p>KernelSU 沒有內建的針對 Zygisk 的支援，因此模組中沒有與 Zygisk 相關的內容，但您可以透過安裝 <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> 以支援 Zygisk 模組，此時 Zygisk 模組的內容與 Magisk 所支援的 Zygisk 完全相同。</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop 是一個模組的設定檔，在 KernelSU 中如果模組中不包含這個檔案，那麼它將不被認為是一個模組；這個檔案的格式如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li>id 必須與這個正則表達式相符：<code>^[a-zA-Z][a-zA-Z0-9._-]+$</code> 例如：✓ <code>a_module</code>，✓ <code>a.module</code>，✓ <code>module-101</code>，✗ <code>a module</code>，✗ <code>1_module</code>，✗ <code>-a-module</code>。這是您的模組的唯一識別碼，發表後將無法變更。</li><li>versionCode 必須是一個整數，用於比較版本。</li><li>其他未在上方提到的內容可以是任何單行字串。</li><li>請確保使用 <code>UNIX (LF)</code> 分行符號類型，而非 <code>Windows (CR + LF)</code> 或 <code>Macintosh (CR)</code>。</li><li>actionIcon 與 webuiIcon 是可選的圖示路徑，會作為管理器中模組 Action 捷徑與 WebUI 捷徑的預設圖示。這些路徑必須是以模組根目錄為 基準的相對路徑。例如：<code>actionIcon=icon/icon.png</code> 會解析為 <code>&lt;MODDIR&gt;/icon/icon.png</code>。</li></ul><div class="tip custom-block"><p class="custom-block-title">動態描述</p><p><code>description</code> 欄位可以在執行階段使用模組配置系統動態覆蓋。詳情請參閱<a href="./module-config.html#overriding-module-description">覆蓋模組描述</a>。</p></div><h3 id="shell-scripts" tabindex="-1">Shell 腳本 <a class="header-anchor" href="#shell-scripts" aria-label="Permalink to &quot;Shell 腳本 {#shell-scripts}&quot;">​</a></h3><p>請閱讀 <a href="#boot-scripts">開機腳本</a> 章節，以瞭解 <code>post-fs-data.sh</code> 和 <code>service.sh</code> 之間的差別。對於大多數模組開發人員來說，如果您只需要執行一個開機腳本，<code>service.sh</code> 應該已經足夠了。 如果您需要在啟動完成後執行腳本，請使用 <code>boot-completed.sh</code>。 如果你想在掛載 overlayfs 後做一些事情，請使用 <code>post-mount.sh</code>。</p><p>在您的模組中的所有腳本中，請使用 <code>MODDIR=\${0%/*}</code> 以取得您的模組基本目錄路徑；請不要在腳本中以硬式編碼的方式加入您的模組路徑。</p><div class="tip custom-block"><p class="custom-block-title">與 Magisk 的差異</p><p>您可以透過環境變數 <code>KSU</code> 來判斷腳本是執行在 KernelSU 還是 Magisk 中，如果執行在 KernelSU，這個值會被設為 <code>true</code>。</p></div><h3 id="system-directories" tabindex="-1"><code>system</code> 目錄 <a class="header-anchor" href="#system-directories" aria-label="Permalink to &quot;\`system\` 目錄 {#system-directories}&quot;">​</a></h3><p>這個目錄的內容會在系統啟動後，以 <code>overlayfs</code> 的方式覆疊在系統的 <code>/system</code> 分區之上，這表示：</p><ol><li>系統中對應目錄的相同名稱的檔案會被此目錄中的檔案覆寫。</li><li>系統中對應目錄的相同名稱的檔案會與此目錄的檔案合併。</li></ol><p>如果您想要刪除系統先前的目錄中的某個檔案或資料夾，您需要在模組目錄中透過 <code>mknod filename c 0 0</code> 以建立一個 <code>filename</code> 的相同名稱的檔案；這樣 overlayfs 系統會自動「whiteout」等效刪除這個檔案 (<code>/system</code> 分割區並未被變更)。</p><p>您也可以在 <code>customize.sh</code> 中宣告一個名為 <code>REMOVE</code> 並且包含一系列目錄的變數以執行移除作業，KernelSU 會自動為您在模組對應目錄執行 <code>mknod &lt;TARGET&gt; c 0 0</code>。例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>上方的清單將會執行：<code>mknod $MODPATH/system/app/YouTuBe c 0 0</code> 和 <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>；並且 <code>/system/app/YouTube</code> 和 <code>/system/app/Bloatware</code> 將會在模組生效前移除。</p><p>如果您想要取代系統的某個目錄，您需要在模組目錄中建立一個相同路徑的目錄，然後為此目錄設定此屬性：<code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code>；這樣 overlayfs 系統會自動將對應目錄取代 (<code>/system</code> 分割區並未被變更)。</p><p>您可以在 <code>customize.sh</code> 中宣告一個名為 <code>REMOVE</code> 並且包含一系列目錄的變數以執行移除作業，KernelSU 會自動為您在模組對應目錄執行相關作業。例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REPLACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>上方的清單將會執行：自動建立目錄 <code>$MODPATH/system/app/YouTube</code> 和 <code>$MODPATH//system/app/Bloatware</code>，然後執行 <code>setfattr -n trusted.overlay.opaque -v y $$MODPATH/system/app/YouTube</code> 和 <code>setfattr -n trusted.overlay.opaque -v y $$MODPATH/system/app/Bloatware</code>；並且 <code>/system/app/YouTube</code> 和 <code>/system/app/Bloatware</code> 將會在模組生效後被取代為空白目錄。</p><div class="tip custom-block"><p class="custom-block-title">與 Magisk 的差異</p><p>KernelSU 的 systemless 機制透過核心的 overlayfs 實作，而 Magisk 目前則是透過 magic mount (bind mount)，兩者的實作方式有很大的差別，但最終的目標是一致的：不修改實際的 <code>/system</code> 分區但修改 <code>/system</code> 檔案。</p></div><p>如果您對 overlayfs 感興趣，建議閱讀 Linux Kernel 關於 <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">overlayfs 的文檔</a></p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>這個檔案的格式與 <code>build.prop</code> 完全相同：每一行都是由 <code>[key]=[value]</code> 組成。</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>如果您的模組需要一些額外 sepolicy 修補，請將這些原則新增至這個檔案中。這個檔案的每一行都將被視為一個原則陳述。</p><h3 id="initrc-injection" tabindex="-1">initrc 注入 <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;initrc 注入 {#initrc-injection}&quot;">​</a></h3><p>KernelSU 提供了一種將自訂 Android Init RC 指令注入系統 <code>init.rc</code> 的機制。這使得模組可以在不修改系統分區的情況下註冊自訂的 Android 服務、設定屬性觸發器或執行其他 Init 語言操作。</p><p>在啟動過程中，KernelSU 的核心模組透過 hook <code>read()</code> 和 <code>fstat()</code> 系統調用，在 Android init 進程讀取 <code>/system/etc/init/hw/init.rc</code> 時，將自訂 RC 內容透明地附加到文件末尾。init 進程會像處理原始 init.rc 內容一樣解析這些注入的指令。</p><p>在使用者空間側，ksud 會將所有已啟用模組的 <code>.rc</code> 檔案合併到一個 <code>modules.rc</code> 檔案中，存放在 <code>/metadata</code> 分區上。每當模組狀態發生變化（安裝、啟用、停用、解除安裝等）時，這個檔案都會被自動重新產生。</p><h4 id="模組-initrc-檔案" tabindex="-1">模組 initrc 檔案 <a class="header-anchor" href="#模組-initrc-檔案" aria-label="Permalink to &quot;模組 initrc 檔案&quot;">​</a></h4><p>在模組目錄中建立一個 <code>initrc/</code> 子目錄，將 <code>.rc</code> 檔案放置其中：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>檔案必須以 <code>.rc</code> 為副檔名。</li><li>只要模組處於啟用狀態，<code>initrc/</code> 目錄下的所有 <code>.rc</code> 檔案都會被包含（無需設定可執行權限）。</li><li>處理的先後順序為：同一目錄內的檔案按<strong>檔案名稱字母順序</strong>排列；模組之間按<strong>模組 ID 字母順序</strong>排列。</li></ul></div><h4 id="通用-initrc-檔案" tabindex="-1">通用 initrc 檔案 <a class="header-anchor" href="#通用-initrc-檔案" aria-label="Permalink to &quot;通用 initrc 檔案&quot;">​</a></h4><p>除了模組層級的 RC 檔案外，您還可以將 <code>.rc</code> 檔案放置在全域目錄中：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">全域 initrc 檔案需要可執行權限</p><p>與模組 <code>initrc/</code> 目錄不同，<code>/data/adb/initrc.d/</code> 中的檔案<strong>必須設定可執行權限</strong>才會被包含。不具有可執行權限的 <code>.rc</code> 檔案會被靜默跳過。</p></div><p>全域 <code>initrc.d/</code> 檔案在所有模組 RC 檔案之前被處理。</p><h4 id="範例" tabindex="-1">範例 <a class="header-anchor" href="#範例" aria-label="Permalink to &quot;範例&quot;">​</a></h4><p>以下是一個註冊自訂 Android 服務的 <code>.rc</code> 檔案範例：</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>此檔案放置在 <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>，將在系統啟動時註冊一個名為 <code>myservice</code> 的服務，並在 <code>sys.boot_completed=1</code> 時啟動它。</p><h4 id="手動重新整理" tabindex="-1">手動重新整理 <a class="header-anchor" href="#手動重新整理" aria-label="Permalink to &quot;手動重新整理&quot;">​</a></h4><p>您可以透過以下指令手動觸發 <code>modules.rc</code> 重新產生（變更將在下次啟動時生效）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>initrc 注入發生在啟動極早期（init 讀取 init.rc 時），<strong>早於</strong> post-fs-data 和所有模組腳本的執行。</li><li>注入的 RC 內容被 init 當作原始 init.rc 的一部分處理，支援所有 Android Init 語言語法（服務定義、觸發器、屬性設定等）。</li><li>在 <strong>late-load 模式</strong>下，initrc 注入<strong>不可用</strong>，因為系統調用 hook 在該模式下不會被安裝。</li><li>可以在 ksud 修補映像檔的時候傳入參數 <code>--no-custom-rc</code> 停用模組 RC 注入。</li></ul></div><h2 id="module-installer" tabindex="-1">模組安裝程式 <a class="header-anchor" href="#module-installer" aria-label="Permalink to &quot;模組安裝程式 {#module-installer}&quot;">​</a></h2><p>KernelSU 的模組安裝程式就是一個可以透過 KernelSU 管理員應用程式刷新的 Zip 檔案，這個 Zip 檔案的格式如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Optional, more details later)</span></span>
<span class="line"><span>│                                           This script will be sourced by update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* 其他模块文件 */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p>KernelSU 模組不支援在 Recovery 中安裝！！</p></div><h3 id="customizing-installation" tabindex="-1">自訂安裝過程 <a class="header-anchor" href="#customizing-installation" aria-label="Permalink to &quot;自訂安裝過程 {#customizing-installation}&quot;">​</a></h3><p>如果您想要控制模組的安裝過程，可以在模組的目錄下建立一個名為 <code>customize.sh</code> 的檔案，這個檔案將會在模組被解壓縮後經由 <strong>source</strong> 調用，如果您的模組需要依據裝置的 API 版本或裝置架構執行一些額外的作業，這個腳本將非常有用。</p><p>如果您想完全控制腳本的安裝過程，您可以在 <code>customize.sh</code> 中宣告 <code>SKIPUNZIP=1</code> 以跳過所有的預設安裝步驟。此時，您需要自行處理所有的安裝過程(例如解壓縮模組、設定權限等)。</p><p><code>customize.sh</code> 腳本以「獨立模式」執行在 KernelSU 的 BusyBox <code>ash</code> shell 中。您可以使用下列變數和函式：</p><h4 id="variables" tabindex="-1">變數 <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;變數 {#variables}&quot;">​</a></h4><ul><li><code>KSU</code> (bool): 標示此腳本執行於 KernelSU 環境中，此變數的值將永遠為 <code>true</code>，您可以透過它與 Magisk 進行區分。</li><li><code>KSU_VER</code> (string): KernelSU 目前的版本名稱 (例如 <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): KernelSU 使用者空間目前的版本代碼 (例如 <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): KernelSU 核心空間目前的版本代碼 (例如 <code>10672</code>)</li><li><code>BOOTMODE</code> (bool): 此變數在 KernelSU 中永遠為 <code>true</code></li><li><code>MODPATH</code> (path): 目前模組的安裝目錄</li><li><code>TMPDIR</code> (path): 可以存放暫存檔的位置</li><li><code>ZIPFILE</code> (path): 目前模組的安裝程式 Zip</li><li><code>ARCH</code> (string): 裝置的 CPU 架構，有這幾種：<code>arm</code>, <code>arm64</code>, <code>x86</code>, or <code>x64</code></li><li><code>IS64BIT</code> (bool): 是否為 64 位元裝置</li><li><code>API</code> (int): 目前裝置的 Android API 版本 (例如 Android 6.0 上為 <code>23</code>)</li><li><code>KSU_UAPI_VER</code> (int): KernelSU 使用者空間 (ksud) 的 UAPI 版本號 (例如 <code>2</code>)。當核心驅動發生破壞性更改時此版本號會遞增，模組可據此判斷相容性。</li><li><code>KSU_RUNTIME_MODE</code> (string): KernelSU 目前的執行模式。可能的值為 <code>built-in</code>（即 GKI 模式，編譯進核心）、<code>lkm</code>（開機時作為核心模組載入）或 <code>late-load</code>（開機後作為核心模組載入）。</li><li><code>KSU_LATE_LOAD</code> (int?): 如果 KernelSU 是在開機後延遲載入的，此變數的值為 <code>1</code>，否則不設定此變數。</li></ul><div class="warning custom-block"><p class="custom-block-title">警告</p><p><code>MAGISK_VER_CODE</code> 在 KernelSU 永遠為 <code>25200</code>，<code>MAGISK_VER</code> 則為 <code>v25.2</code>，請不要透過這兩個變數來判斷是否為 KernelSU！</p></div><h4 id="functions" tabindex="-1">函式 <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;函式 {#functions}&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    print &lt;msg&gt; to console</span></span>
<span class="line"><span>    Avoid using &#39;echo&#39; as it will not display in custom recovery&#39;s console</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    print error message &lt;msg&gt; to console and terminate the installation</span></span>
<span class="line"><span>    Avoid using &#39;exit&#39; as it will skip the termination cleanup steps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    this function is a shorthand for the following commands:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    for all files in &lt;directory&gt;, it will call:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    for all directories in &lt;directory&gt; (including itself), it will call:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h2 id="boot-scripts" tabindex="-1">開機腳本 <a class="header-anchor" href="#boot-scripts" aria-label="Permalink to &quot;開機腳本 {#boot-scripts}&quot;">​</a></h2><p>在 KernelSU 中，依據腳本執行模式的不同分為兩種：post-fs-data 模式和 late_start 服務模式。</p><ul><li><p>post-fs-data 模式</p><ul><li>這個階段是 <strong>阻塞</strong> 的。在執行完成之前或 10 秒鐘之後，開機程序會被暫停。</li><li>腳本在任何模組被掛接之前執行。這使模組開發人員可以在模組被掛接之前動態調整他們的模組。</li><li>這個階段發生在 Zygote 啟動之前，這意味著 Android 中的一切。</li><li><strong>警告</strong>: 使用 <code>setprop</code> 會導致開機程序死鎖！請使用 <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> 替代。</li><li><strong>僅在必要時在此模式中執行腳本</strong>。</li></ul></li><li><p>late_start 服務模式</p><ul><li>這個階段是 <strong>非阻塞</strong> 的。您的腳本會與其餘的啟動程序<strong>平行</strong>執行。</li><li><strong>大多數腳本建議在這種模式下執行</strong>。</li></ul></li></ul><p>在 KernelSU 中，開機腳本依據存放位置的不同還分為兩種：一般腳本和模組腳本。</p><ul><li><p>一般腳本</p><ul><li>放置於 <code>/data/adb/post-fs-data.d</code> 或 <code>/data/adb/service.d</code> 中。</li><li>僅有腳本被設為可執行 (<code>chmod +x script.sh</code>) 時才會被執行。</li><li>在 <code>post-fs-data.d</code> 中的腳本以 post-fs-data 模式執行，在 <code>service.d</code> 中的腳本以 late_start 服務模式執行。</li><li>模組<strong>不應</strong>在安裝程序中新增一般腳本。</li></ul></li><li><p>模組腳本</p><ul><li>放置於模組自己的資料夾中。</li><li>僅有在模組啟用時才會執行。</li><li><code>post-fs-data.sh</code> 以 post-fs-data 模式運行，<code>post-mount.sh</code> 在 overlayfs 掛載後運行，而 <code>service.sh</code> 則以 late_start 服務模式運行，<code>boot-completed</code> 在 Android 系統啟動完畢後以服務模式運作。</li></ul></li></ul><p>所有啟動腳本都將在 KernelSU 的 BusyBox ash shell 中執行，並啟用<strong>獨立模式</strong>。</p><h3 id="boot-scripts-process-explanation" tabindex="-1">開機腳本解釋 <a class="header-anchor" href="#boot-scripts-process-explanation" aria-label="Permalink to &quot;開機腳本解釋 {#boot-scripts-process-explanation}&quot;">​</a></h3><p>以下是Android的相關啟動流程（部分省略），其中包括KernelSU的運行（帶前導星號），可以幫助您更好地理解這些模組腳本的用途：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0. Bootloader (nothing on screen)</span></span>
<span class="line"><span>load patched boot.img</span></span>
<span class="line"><span>load kernel:</span></span>
<span class="line"><span>    - GKI mode: GKI kernel with KernelSU integrated</span></span>
<span class="line"><span>    - LKM mode: stock kernel</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. kernel exec init (oem logo on screen):</span></span>
<span class="line"><span>    - GKI mode: stock init</span></span>
<span class="line"><span>    - LKM mode: exec ksuinit, insmod kernelsu.ko, exec stock init</span></span>
<span class="line"><span>mount /dev, /dev/pts, /proc, /sys, etc.</span></span>
<span class="line"><span>property-init -&gt; read default props</span></span>
<span class="line"><span>read init.rc</span></span>
<span class="line"><span>  *initrc injection: Kernel hook appends KernelSU core RC and module modules.rc to init.rc</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>early-init -&gt; init -&gt; late_init</span></span>
<span class="line"><span>early-fs</span></span>
<span class="line"><span>   start vold</span></span>
<span class="line"><span>fs</span></span>
<span class="line"><span>  mount /vendor, /system, /persist, etc.</span></span>
<span class="line"><span>post-fs-data</span></span>
<span class="line"><span>  *safe mode check</span></span>
<span class="line"><span>  *execute general scripts in post-fs-data.d/</span></span>
<span class="line"><span>  *load sepolicy.rule</span></span>
<span class="line"><span>  *mount tmpfs</span></span>
<span class="line"><span>  *execute module scripts post-fs-data.sh</span></span>
<span class="line"><span>    **(Zygisk)./bin/zygisk-ptrace64 monitor</span></span>
<span class="line"><span>  *(pre)load system.prop (same as resetprop -n)</span></span>
<span class="line"><span>  *remount modules /system</span></span>
<span class="line"><span>  *execute general scripts in post-mount.d/</span></span>
<span class="line"><span>  *execute module scripts post-mount.sh</span></span>
<span class="line"><span>zygote-start</span></span>
<span class="line"><span>load_all_props_action</span></span>
<span class="line"><span>  *execute resetprop (actual set props for resetprop with -n option)</span></span>
<span class="line"><span>... -&gt; boot</span></span>
<span class="line"><span>  class_start core</span></span>
<span class="line"><span>    start-service logd, console, vold, etc.</span></span>
<span class="line"><span>  class_start main</span></span>
<span class="line"><span>    start-service adb, netd (iptables), zygote, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. kernel2user init (rom animation on screen, start by service bootanim)</span></span>
<span class="line"><span>*execute general scripts in service.d/</span></span>
<span class="line"><span>*execute module scripts service.sh</span></span>
<span class="line"><span>*set props for resetprop without -p option</span></span>
<span class="line"><span>  **(Zygisk) hook zygote (start zygiskd)</span></span>
<span class="line"><span>  **(Zygisk) mount zygisksu/module.prop</span></span>
<span class="line"><span>start system apps (autostart)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>boot complete (broadcast ACTION_BOOT_COMPLETED event)</span></span>
<span class="line"><span>*execute general scripts in boot-completed.d/</span></span>
<span class="line"><span>*execute module scripts boot-completed.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. User operable (lock screen)</span></span>
<span class="line"><span>input password to decrypt /data/data</span></span>
<span class="line"><span>*actual set props for resetprop with -p option</span></span>
<span class="line"><span>start user apps (autostart)</span></span></code></pre></div><p>如果您對 Android 的 Init 語言感興趣，建議閱讀它的 <a href="https://android.googlesource.com/platform/system/core/+/master/init/README.md" target="_blank" rel="noreferrer">文檔</a>.</p><h2 id="late-load-mode" tabindex="-1">Late-load 模式 <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Late-load 模式 {#late-load-mode}&quot;">​</a></h2><p>除了上述標準啟動流程外，KernelSU 還支援 <strong>late-load 模式</strong>，用於 LKM（可載入核心模組）場景。在該模式下，KernelSU 核心模組在<strong>系統完全啟動後</strong>載入，而非在 init 過程中載入。</p><h3 id="什麼時候觸發-late-load" tabindex="-1">什麼時候觸發 late-load？ <a class="header-anchor" href="#什麼時候觸發-late-load" aria-label="Permalink to &quot;什麼時候觸發 late-load？&quot;">​</a></h3><p>透過執行 <code>ksud late-load</code> 命令觸發。該命令會：</p><ol><li>偵測當前 KMI 版本，從內嵌資源中載入對應的 <code>kernelsu.ko</code>。</li><li>執行模組初始化（SELinux 規則、白名單、feature 等），這些工作在標準啟動中發生在 boot 階段。</li></ol><p>由於系統已經完全運行，某些啟動時的機制不可用或不需要。</p><h3 id="與標準啟動的差異" tabindex="-1">與標準啟動的差異 <a class="header-anchor" href="#與標準啟動的差異" aria-label="Permalink to &quot;與標準啟動的差異&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行為</th><th style="text-align:center;">標準啟動</th><th style="text-align:center;">Late-load 模式</th></tr></thead><tbody><tr><td>核心模組由 init (PID 1) 載入</td><td style="text-align:center;">是</td><td style="text-align:center;">否（啟動後載入）</td></tr><tr><td>initrc 注入（模組 <code>.rc</code> 檔案注入 init.rc）</td><td style="text-align:center;">是</td><td style="text-align:center;">不可用</td></tr><tr><td>ksud 的 kprobe 鉤子 (execve/read/fstat/input)</td><td style="text-align:center;">是</td><td style="text-align:center;">跳過</td></tr><tr><td>安全模式偵測（音量鍵）</td><td style="text-align:center;">是</td><td style="text-align:center;">始終停用</td></tr><tr><td>啟動日誌擷取 (logcat/dmesg)</td><td style="text-align:center;">是</td><td style="text-align:center;">跳過</td></tr><tr><td>Magisk 共存偵測</td><td style="text-align:center;">是</td><td style="text-align:center;">跳過</td></tr><tr><td><code>post-fs-data</code> 事件通知核心</td><td style="text-align:center;">是</td><td style="text-align:center;">跳過</td></tr><tr><td><code>boot-completed</code> 事件通知核心</td><td style="text-align:center;">是</td><td style="text-align:center;">初始化時直接設定</td></tr><tr><td><code>post-fs-data.sh</code> / <code>post-fs-data.d/</code> 指令碼</td><td style="text-align:center;">是</td><td style="text-align:center;">由 <code>late-load</code> 階段替代</td></tr><tr><td><code>system.prop</code> 載入</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td>OverlayFS 掛載（metamodule）</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>post-mount.sh</code> / <code>post-mount.d/</code> 指令碼</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>service.sh</code> / <code>service.d/</code> 指令碼</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>boot-completed.sh</code> / <code>boot-completed.d/</code> 指令碼</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>KSU_LATE_LOAD</code> 環境變數</td><td style="text-align:center;">未設定</td><td style="text-align:center;">設定為 <code>1</code></td></tr><tr><td>核心 info 標誌位 <code>0x4</code></td><td style="text-align:center;">未設定</td><td style="text-align:center;">已設定</td></tr></tbody></table><h3 id="指令碼執行順序" tabindex="-1">指令碼執行順序 <a class="header-anchor" href="#指令碼執行順序" aria-label="Permalink to &quot;指令碼執行順序&quot;">​</a></h3><p>在 late-load 模式下，指令碼執行順序如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. 載入 kernelsu.ko（如果尚未載入）</span></span>
<span class="line"><span>  2. 釋放二進位檔案、處理模組更新、載入 SELinux 規則、初始化 feature</span></span>
<span class="line"><span>  3. 執行 late-load.d/ 通用指令碼和模組的 late-load 指令碼（阻塞）</span></span>
<span class="line"><span>  4. 載入 system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. 執行 metamodule mount 指令碼（OverlayFS 掛載）</span></span>
<span class="line"><span>  6. 執行 post-mount.d/ 通用指令碼和模組的 post-mount.sh（阻塞）</span></span>
<span class="line"><span>  7. 執行 service.d/ 通用指令碼和模組的 service.sh（非阻塞）</span></span>
<span class="line"><span>  8. 執行 boot-completed.d/ 通用指令碼和模組的 boot-completed.sh（非阻塞）</span></span></code></pre></div><h3 id="late-load-專用指令碼" tabindex="-1">Late-load 專用指令碼 <a class="header-anchor" href="#late-load-專用指令碼" aria-label="Permalink to &quot;Late-load 專用指令碼&quot;">​</a></h3><p>模組可以提供 <code>late-load.sh</code> 指令碼，該指令碼<strong>僅在 late-load 模式下執行</strong>，作為 <code>post-fs-data.sh</code> 的替代。該指令碼在 OverlayFS 掛載之前執行，與標準流程中的 <code>post-fs-data.sh</code> 時機類似。</p><p>此外，通用指令碼可以放置在 <code>/data/adb/late-load.d/</code> 目錄下，在該階段執行。</p><h3 id="在指令碼中偵測-late-load-模式" tabindex="-1">在指令碼中偵測 late-load 模式 <a class="header-anchor" href="#在指令碼中偵測-late-load-模式" aria-label="Permalink to &quot;在指令碼中偵測 late-load 模式&quot;">​</a></h3><p>模組可以透過 <code>KSU_LATE_LOAD</code> 環境變數偵測當前是否處於 late-load 模式：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 當前處於 late-load 模式</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>這使得模組可以據此調整自身行為，例如跳過僅在早期啟動時才需要的操作。</p>`,109)])])}const m=a(l,[["render",p]]);export{u as __pageData,m as default};
